/**
 * @fileoverview Test the overriding of a private method
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-private-method-override'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-private-method-override', rule, {

    valid: [
        {
            settings: {
                extjs: {
                    version: '4'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',

                    // in version 4, this method did not exist (and neither did a config) so this will not produce an error
                    getActiveCounter: false
                });
            `
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomButton', {
                    extend: 'Ext.button.Button',
                    // initComponent on the Ext.button.Button class is undocumented
                    // and thus doxi says it is a private method.
                    // however, it is still ok to override this template method
                    initComponent: function() {
                        this.callParent(arguments);
                    }
                });
                Ext.define('MyCustomTabPanel', {
                    extend: 'Ext.tab.Panel',
                    // initComponent on the Ext.tab.Panel class is undocumented
                    // and thus doxi says it is a private method.
                    // however, it is still ok to override this template method
                    initComponent: function() {
                        this.callParent(arguments);
                    }
                });
                Ext.define('MyApp.view.View', {
                    extend: 'Ext.view.View',
                    // afterRender on the Ext.view.View class is undocumented
                    // and thus doxi says it is a private method.
                    // however, it is still ok to override this template method
                    afterRender: function () {}
                });
            `
        }
    ],

    invalid: [
        {
            settings: {
                extjs: {
                    version: '4'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',

                    // should warn about overriding this private method
                    getAutoId: function () {},

                    // in version 4, this method did not exist (and neither did a config) so this code is valid
                    getActiveCounter: false
                });               
            `,
            errors: [
                { message: /Override of private method 'getAutoId' found for 'Ext.Component'/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',

                    // should warn about overriding this private method
                    getAutoId: function () {},

                    // should warn about overriding this private accessor method
                    // since, beginning with v5, 'activeCounter' was added as a private accessor config
                    getActiveCounter: false
                });
            `,
            errors: [
                { message: /Override of private method 'getAutoId' found for 'Ext.Component'/ },
                { message: /Override of private method 'getActiveCounter', for the 'activeCounter' config, found for 'Ext.Component'/ }
            ]
        },
        {
            settings: {
                extjs: {
                    version: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomController', {
                    extend: 'Ext.app.ViewController',
                    addConfig: true, // example of accidentaly overriding a method with a primitive
                    addMember: null, // example of accidentaly overriding a method with null
                    borrow: undefined, // example of accidentaly overriding a method with undefined
                    _addDeclaredListeners: Ext.emptyFn,  // example of accidentaly overriding a method with function reference
                    link: function () {}  // example of accidentaly overriding a method with a FunctionExpression
                });
            `,
            errors: [
                { 
                    message: /Override of private method 'addConfig' found for 'Ext.app.ViewController'/,
                    type: 'Property'
                },
                { 
                    message: /Override of private method 'addMember' found for 'Ext.app.ViewController'/,
                    type: 'Property'
                },
                { 
                    message: /Override of private method 'borrow' found for 'Ext.app.ViewController'/,
                    type: 'Property'
                },
                { 
                    message: /Override of private method '_addDeclaredListeners' found for 'Ext.app.ViewController'/,
                    type: 'Property'
                },
                { 
                    message: /Override of private method 'link' found for 'Ext.app.ViewController'/,
                    type: 'Property'
                }
            ]
        }
    ]
});
